INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ab83ae44-e2d4-4576-b73b-846c727ce68e', '21feff02-016d-46e2-bb9d-c27495133b1b', '71. óra: Egyenes arányosság', 'Egyenes arányosság tulajdonságai: hányados állandó, megkétszereződés esetén a másik is megkétszereződik.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "91ba3aef-219e-40b3-90ed-3a400cfe2d9b", "text": "Mit jelent az egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "733128f0-b2a8-4c5b-970f-68ff900c6d2f", "text": "Ha az egyik mennyiség hányszorosára változik, a másik mennyiség is ugyanannyiszorosára változik", "isCorrect": true}, {"id": "c411bad7-adfe-43ff-9866-9b8db725ba69", "text": "Ha az egyik nő, a másik felére csökken", "isCorrect": false}, {"id": "5dd7f19c-f767-43b4-baba-57b619c0b990", "text": "Ha a két mennyiség összege 100", "isCorrect": false}, {"id": "73158c6d-27c5-4422-949e-213b421fd5c2", "text": "Ha a két mennyiség szorzata állandó", "isCorrect": false}], "timeLimit": 15}, {"id": "02fc78cb-bc14-4ac1-8546-dcacbc50e22c", "text": "Egyenes arányosság esetén a két összetartozó érték hányadosa állandó.", "type": "true-false", "options": [{"id": "8a1ed49c-ed9c-4eca-afbb-d0a077e4c10b", "text": "Igaz", "isCorrect": true}, {"id": "6a262a4d-8371-4da8-9749-744cd130bf76", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56080748-bb2d-4631-8d03-b4721038ce1d", "text": "Ha 2 kg alma 800 Ft, mennyibe kerül 6 kg alma? (800 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2400"}, {"id": "493f4e2f-2be1-43cd-9062-64716dd2aba2", "text": "Ha 3 füzet 600 Ft, mennyibe kerül 1 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "dc589340-78ef-44a0-982c-42392be1852a", "text": "Melyik pár között van egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "d154d6c4-1aef-4935-b468-7b653be60e5d", "text": "Az azonos árú termék tömege és a fizetendő összeg", "isCorrect": true}, {"id": "d4492f26-e0b6-4011-9a8b-ffe35a625fdd", "text": "Az ember életkora és a magassága felnőttként", "isCorrect": false}, {"id": "b6f23ae3-9cf9-4495-9c18-4f77d704d241", "text": "A téglalap két oldala rögzített területnél", "isCorrect": false}, {"id": "7038762b-f25f-48eb-89a2-3a3b905b199b", "text": "A sebesség és az idő adott úton", "isCorrect": false}], "timeLimit": 15}, {"id": "ecf0ce57-0741-4147-8d0c-34d97c75a408", "text": "Ha a megvásárolt mennyiséget felére csökkentjük, a fizetendő ár is a felére csökken.", "type": "true-false", "options": [{"id": "8bce4f39-0b5c-4797-aa60-7ed2dd2c01a1", "text": "Igaz", "isCorrect": true}, {"id": "d16689ab-5353-4ecb-ae42-b722b8440d45", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b84db941-f9f3-470a-a2a9-12a215ce5e13", "text": "Ha 5 l üdítő 2000 Ft, mennyi 10 l üdítő ára? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e190bfe3-37b7-4d82-9f7f-f4902210e47c', '21feff02-016d-46e2-bb9d-c27495133b1b', '72. óra: Egyenes arányosság grafikonja', 'Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "e722459d-6236-4ad3-b4bc-6f8f40d1e550", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "230064b1-57e3-4290-87f7-1edda9ead965", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "15b24add-d2d5-4032-927d-afd076e02d81", "text": "Parabola", "isCorrect": false}, {"id": "86748c6e-cd8f-496f-b075-8f0e73ed75f5", "text": "Körvonal", "isCorrect": false}, {"id": "556e0bde-6b92-462d-95fb-af8e10b4cd41", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "bc4af676-cd80-4963-8c49-63a3f8bb68ce", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "6e0549e3-aecf-481b-9392-e567375f2fae", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "eb2cf584-ea76-47af-a6a9-73593602fc59", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5c532257-7f20-4771-aa6a-d89814e6c16d", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "d4e05014-1ac5-4061-a87b-0718c946e0ed", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "d790cf7e-eedf-4d8b-a3a3-418aeed5139a", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "e5df8370-9e37-40b3-968f-96082044c09b", "text": "Igaz", "isCorrect": true}, {"id": "a46af412-d20e-4e2c-8ee3-75dbfb44d683", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a79c084c-a371-40d0-952f-57027b26ff10", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "3d4fa0df-5024-41c3-917e-20185eac23b6", "text": "Igaz", "isCorrect": true}, {"id": "f630149b-0b5c-44e1-9226-d7af3884e705", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2139c435-fe90-49b4-b110-da11770ece39", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "30f8ebaf-143f-4c1b-bb1a-9d4e84bfa69f", "text": "Igaz", "isCorrect": true}, {"id": "880500b0-d1f3-4c68-b6c1-b69b31ae9a7a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b43a4874-7826-435c-8aa9-3c350b834d1e', '21feff02-016d-46e2-bb9d-c27495133b1b', '73. óra: Gyakorlóóra', 'Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "74fc8151-8cae-4cf2-a384-68106629a7b9", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "9091c305-e039-43c8-9ff5-d8d25fddae80", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "26bfbfbc-e5cf-467c-8513-27582a3701e9", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "aee91654-3e48-4edc-94ba-d15a417ce738", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "5c8d31d8-fb1e-4163-9d01-8ec5aca8c43f", "text": "Igaz", "isCorrect": true}, {"id": "a73c6030-e0f9-4aed-bd94-be12aa9ecf1f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9761189f-881e-4fcd-860b-0420a9ac7f9e", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "4dd82146-7274-4f9a-889f-5fbae7a9bc7b", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "f9bd55fc-b280-455a-830d-5a60257df508", "text": "Igaz", "isCorrect": true}, {"id": "714e9970-f604-442f-b985-c4a384a2c7c4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ca597f3d-9b1d-43cf-93e0-d8f5dcf0bb32", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9fddb8a1-5c29-4ea9-a383-160c87b8be65', '21feff02-016d-46e2-bb9d-c27495133b1b', '74. óra: Matematikai játékok', 'Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d1551006-fd05-4678-b328-e634b924b8af", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "a5e81376-684c-4883-9cb8-179a53012e2f", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "c872cab0-a932-46b7-9253-58b9ba797a91", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "472b78a6-c1ca-44ae-bbb1-bf5225dffb48", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "9d656814-792e-4d53-bd56-65be09a4af40", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "d8e78399-a7e4-40cf-8d62-715430188f2a", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "3bb74d07-9584-46d7-85ed-b60f03cce51c", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "9b992b43-8b09-4c25-83dc-c9f6b866ab96", "text": "Igaz", "isCorrect": true}, {"id": "2d11e4fe-4151-48bb-af76-caf54f630dc3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "baa20a8c-9c86-4f39-9681-039148947227", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "db4374d3-5890-46c0-a8ee-7ac5f7dd7655", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "d9bb6a79-e21d-4a6e-80d2-156d4254b31a", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "8dd9aa2d-48f8-425b-ac7f-f40ce8aa4800", "text": "Igaz", "isCorrect": true}, {"id": "14994f83-5237-413e-9cbc-bd6800cad211", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2791b9c1-d18d-4b54-88af-722f3aee7865", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "211326c1-c4f1-4bba-9247-b3b3b8c20675", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "4706e63e-c0e0-4803-a205-e5093ea44a0a", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "fa1cbe29-b759-431d-8e0b-dd8c0dfee9f8", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "09b633cd-ef52-4b65-8762-4055e5a6345a", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ff141c1c-02ac-4b13-9369-85ac1cdb4234', '21feff02-016d-46e2-bb9d-c27495133b1b', '75. óra: Szabályok, megfeleltetések', 'Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "a78f1165-2bb4-4718-bb62-3cb3ae506f52", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "d04a083f-a64e-4374-8917-9ca8302a596b", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "14aaca30-a266-442a-83e4-3b2070218438", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "272f9bb2-410e-471f-81e6-21a28894bf21", "text": "Igaz", "isCorrect": true}, {"id": "b01444ba-d40d-4cd8-9651-8194085bca47", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bc557442-78c7-4ed1-be70-c6e15b4cc6a6", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "f5f536b2-6176-48fd-ae8f-06e42cfca240", "text": "Melyik sorozat szabálya a ''Hozzáadás 5-tel''?", "type": "multiple-choice", "options": [{"id": "12b2bfef-749e-4faa-b871-b593a6d5b2bd", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "457c8a47-bacd-4c23-b6cf-26fb7ed12128", "text": "5, 25, 125", "isCorrect": false}, {"id": "aaa9612d-1682-48df-9535-8c670bd1e368", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "76d00dfb-a099-4487-9fe1-c359b38d57ed", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "d99145bb-7974-40f9-82ec-2cde3380d57c", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "368ab3c7-6b7e-49d0-8b55-442cae346c11", "text": "Igaz", "isCorrect": true}, {"id": "8228c017-fb02-4183-9995-e9b416c7e4fa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dfb9f093-6f44-42dd-a860-ad91f0a65bc5", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5ffa6870-f851-4a7f-8384-5db9e544404d', '21feff02-016d-46e2-bb9d-c27495133b1b', '76. óra: Gyakorlóóra', 'Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "6e69d566-c90d-4d90-8c96-a7e625ec1082", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "8375575a-c80d-4f8c-ac6a-782c50337be0", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "a012880f-52d1-42ee-be57-c7985a2caaea", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "4c6bced6-d02f-48d7-92a6-c366250abc28", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "4d3a630a-b32a-4926-8033-3bf67379865b", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "9fef6666-d60b-44ba-9ab5-b40e63653383", "text": "Igaz", "isCorrect": true}, {"id": "1ecbf86e-8e7b-4fae-a028-e1a25cb44503", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "925ccff5-634a-4397-a8e1-47a8cefb4abe", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "63eda469-7722-4b7c-9616-5e8ec26e4990", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "a1ceef6d-5f83-401a-9f44-def80984fc3c", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "5931af8d-60ae-4792-b177-43357400009d", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "3b3b10e1-8161-4cbf-90f6-6470d3bd30d7", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "6f20948c-1d6b-419c-8ade-d15a15560e59", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "e4e95e87-a5ff-4cfc-8711-d8bf2f60c8f5", "text": "Igaz", "isCorrect": true}, {"id": "39f1440c-781b-4b66-9d82-f1a5355f741f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e6d06194-ae20-4377-8e8e-f24b6d7b8d0f', '21feff02-016d-46e2-bb9d-c27495133b1b', '77. óra: Törtrész', 'Törtrész kiszámítása és kapcsolata az egyenes arányossággal.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "1124323a-a23f-4e44-8d3b-1a326add61d2", "text": "Hogyan számítjuk ki egy mennyiség 3/5 részét?", "type": "multiple-choice", "options": [{"id": "67a24be6-ea60-46a0-bae5-a95abf3745b3", "text": "Elosztjuk 5-tel és megszorozzuk 3-mal (vagy megszorozzuk 3/5-tel)", "isCorrect": true}, {"id": "15350671-a244-4e99-adc9-237b7dd9abc7", "text": "Megszorozzuk 5-tel és elosztjuk 3-mal", "isCorrect": false}, {"id": "138deec0-c292-4626-83f2-371498668691", "text": "Hozzáadunk 3/5-öt", "isCorrect": false}, {"id": "29a8bbde-a831-45d1-a2ff-b12bfc0ca2a1", "text": "Kivonunk 3/5-öt", "isCorrect": false}], "timeLimit": 15}, {"id": "7861c2e6-cb56-4a05-ab6d-42bb52c18b3f", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "68f76d5d-a387-4cf9-9731-6af338d99c84", "text": "Mennyi 150-nek a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "b1209847-1c0a-445a-b5a7-b43e12e07bf8", "text": "A törtrész kiszámítása egyenesen arányos a megadott tört nagyságával.", "type": "true-false", "options": [{"id": "22cf4439-7be7-4820-829c-944d3e40dcd4", "text": "Igaz", "isCorrect": true}, {"id": "325de82c-e55a-4786-97eb-173e1a062a60", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2f876cba-f330-4cc0-8144-fd6aab64999e", "text": "Mennyi 200-nak az 1/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "57c36aab-992e-452e-9c1f-a26aeaf16c09", "text": "Ha egy mennyiség 1/2 része 30, mennyi a teljes mennyiség? (30 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "7aede838-e363-4109-a828-8ddae3c6e385", "text": "Mennyi 90-nek a 4/9 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('90e1e45c-6c63-4938-b4b0-0eb71b40a976', '21feff02-016d-46e2-bb9d-c27495133b1b', '78. óra: Feladatmegoldás', 'Összetett feladatok megoldása törtrész kiszámításával.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "bed78a15-3972-4c95-99db-46bf27debe41", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldalt olvastunk el?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "26877324-27a9-4705-9804-4b9d1f912243", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldal van még hátra? (600 - 360)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "240"}, {"id": "587578c7-ae2f-40a1-9dee-321eb68c84d1", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ot költött el? (4000 * 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "b9800b3c-1703-43c1-b07d-b0e627fe75f6", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ja maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "5a26c797-4ab1-4dca-8cc4-cb935f3f2fbd", "text": "Ha a törtrész kiszámítása után a maradékot keresük, a teljesből kivonjuk a törtrészt.", "type": "true-false", "options": [{"id": "f56f3b8d-d588-4a9b-be9f-897a64498b5f", "text": "Igaz", "isCorrect": true}, {"id": "15aa71c5-0890-4d17-8d12-3b47efd38208", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bec909d5-11fd-4f64-b64d-9d04d3e900f6", "text": "Mennyi 120-nak a 5/6 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "a8324273-efef-481a-85b5-586f52264ad4", "text": "A törtrész kiszámítása fontos a pénzügyi és mindennapi döntésekben.", "type": "true-false", "options": [{"id": "c12e5073-28b3-4fe8-a008-92cc72ffd855", "text": "Igaz", "isCorrect": true}, {"id": "f7bffb79-5e75-440a-b3c1-0a851c3e03f2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ffe6f4d9-2d2d-4755-ae56-676220eba289', '21feff02-016d-46e2-bb9d-c27495133b1b', '79. óra: Számonkérés', 'Számonkérés az arány, egyenes arányosság és törtrész témakörökből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "5063f7d7-ff13-4767-b2c1-2548f2f31592", "text": "1. Mennyi a 6 : 18 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "76a68379-5f31-4f42-95f8-17ae084bf900", "text": "1 : 3", "isCorrect": true}, {"id": "e765ed1f-d628-4ee3-9aa9-aed5dadf34f1", "text": "1 : 2", "isCorrect": false}, {"id": "543bda47-1fbe-4961-bc63-560fd2fd0e9b", "text": "3 : 1", "isCorrect": false}, {"id": "26e07898-a13a-4298-b58f-740f3846a985", "text": "2 : 3", "isCorrect": false}], "timeLimit": 15}, {"id": "abfa88a8-c63b-452d-97e7-662a7fe124ae", "text": "2. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "6ba5eac4-4e4e-45cd-888c-616a44c9ee40", "text": "3. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "74fd0676-62a1-4ee0-9b60-f2693fe2e506", "text": "4. Ha 3 kg alma 900 Ft, mennyibe kerül 5 kg alma?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "a14dab02-07d7-4ee9-8881-d658c2277148", "text": "5. Mennyi 120-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "84c92ebd-cb08-47af-9629-d27e387f819a", "text": "6. Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "3b554d9a-7fd1-4eaf-9cad-fa93b1636025", "text": "Igaz", "isCorrect": true}, {"id": "c1d7460d-cf7a-491a-9637-4d03f341973e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3a3d6971-b9c8-48f9-8831-c0abfaefd704", "text": "7. Mi a hiányzó szám a sorozatban: 4, 8, 12, 16, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "27df85c9-a3aa-4646-a5ac-21715fe91139", "text": "8. Ha egy mennyiség 1/3-a 15, mennyi az egész mennyiség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "88ba0a5d-530f-46c2-abf6-c06d1852f337", "text": "9. Két mennyiség aránya hányados formájában is felírható.", "type": "true-false", "options": [{"id": "8a1c5b62-f90f-4488-9e57-95351feb1509", "text": "Igaz", "isCorrect": true}, {"id": "a6fa2d25-8048-4d47-b200-5a5fa20f6172", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "566fa71f-ba67-4bf1-8dec-70dee4b4b423", "text": "10. Mennyi 50-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('be5dd04c-df8b-46dd-a518-52c04614822d', '21feff02-016d-46e2-bb9d-c27495133b1b', '80. óra: Létraverseny I.', 'Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8933382b-9149-4af1-b126-73401cd0463d", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "8c9347f8-34f3-44c8-96e7-5e9dd6d4c7f5", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "339e25ca-85b1-479c-80b0-37c4f547da97", "text": "1 : 3", "isCorrect": true}, {"id": "90624f22-0828-4152-b63a-17a1cccdfa34", "text": "1 : 5", "isCorrect": false}, {"id": "5fb86f9e-c2b3-44be-ab1a-a02afe4fb651", "text": "3 : 1", "isCorrect": false}, {"id": "7db8ec62-a560-48c8-81b0-a05c94c992c8", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "b95c2cfa-af1b-4691-88fa-0429712c0cc9", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "d3f7f77a-9fb2-4bbc-8b1b-7ea032d36657", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "a66969b9-3254-493b-924e-3fb4f2e50082", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "58fce205-ad03-44b8-8cd6-392d0f0d885c", "text": "Igaz", "isCorrect": true}, {"id": "9050e3bc-f9ba-452b-b444-cf950d5c4095", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1d3fa257-3c9f-49bf-94f7-d9467f7e1ccc", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e07029ed-040d-4cd7-9d45-34be4b2b5881", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "79277b01-25a6-44d4-8fda-b42b9b409773", "text": "Igaz", "isCorrect": true}, {"id": "14d897ab-6216-4093-a5a8-822e25e569c1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;